<section class="card"><h2>Other Income</h2><p>Record courtyard events and other activities separately from guest stays. Recording an advance does not yet recognise revenue.</p><?php if($form!=='income_record')finance_action('Record Activity Payment','income_record');?><div class="finance-scroll"><table><thead><tr><th>Receipt / Date</th><th>Payer / Activity</th><th>Amount / Method</th><th>Recorded By</th><th>Service Status</th></tr></thead><tbody><?php foreach(array_reverse($incomeRows) as $income):$complete=$income['data']['treatment']==='earned';foreach($events as $e)if($e['kind']==='income_completed'&&$e['target_type']==='income'&&(int)$e['target_id']===(int)$income['id'])$complete=true;?><tr><td>Activity #<?=(int)$income['id']?><br><?=access_h(display_date($income['created_at']))?></td><td><?=access_h($income['data']['payer'])?><br><?=access_h($income['data']['activity'])?></td><td><?=access_h(fm($income['amount_minor']))?> · <?=access_h(strtoupper($income['data']['method']))?></td><td><?=access_h($income['actor_name'])?></td><td><?=$complete?'Service Completed':'Advance Received'?><?php if(!$complete)finance_action('Mark Service Delivered','income_complete',$income['id']);?></td></tr><?php endforeach?><?php if(!$incomeRows):?><tr><td colspan="5">No activity payments recorded.</td></tr><?php endif?></tbody></table></div></section>
